import { useCallback, useEffect, useMemo, useState } from 'react'
import { useI18n } from '../../i18n/I18nProvider'
import { apiGet, apiPost } from '../../lib/api'
import { useToast } from '../../lib/Toast'
import { CollectionBuilder } from './CollectionBuilder'

/**
 * Marketplace — browse an online catalog of content packs and install them
 * into the current world. Catalog URL is configured in admin settings under
 * `content_marketplace.catalog_url`. Each pack carries `type` (character /
 * item / item_bundle / rule / states / location), tags, size, and an
 * optional preview image. Install streams the ZIP to the backend, which
 * dispatches to the matching importer (same code path used by the local
 * tab buttons).
 */

interface Pack {
  id: string
  type: string
  name?: string
  slug?: string
  version?: string
  size_bytes?: number
  image_count?: number
  room_count?: number
  tags?: string[]
  description?: string
  preview_image?: string
  download_url?: string
  checksum_sha256?: string
  // Only present on type=collection — the index.json may include a contents
  // list so the UI can preview what's inside without downloading the ZIP.
  contents?: Array<{ type: string; name: string }>
}

interface Catalog {
  packs: Pack[]
  configured?: boolean
  stale?: boolean
  source_url?: string
  catalog_id?: string
  catalog_name?: string
  _fetched_at?: number
}

interface CatalogRef {
  id: string
  name: string
  url: string
}

const PRETTY_TYPE: Record<string, string> = {
  character: 'Character',
  item: 'Item',
  item_bundle: 'Item Bundle',
  rule: 'Rule',
  states: 'States',
  location: 'Location',
  prop: 'Prop',
  collection: 'Collection',
  skill_package: 'Skill Package',
}

// Pack types that install executable code — require an explicit trust
// confirmation before install (kept in sync with the backend CODE_PACK_TYPES).
const CODE_PACK_TYPES = new Set(['skill_package'])

/**
 * Whether installing this pack brings a character in — directly, or as a
 * sub-pack of a collection (the catalog's `contents` list says so without a
 * download). Those are the packs that get the import-mode choice, because a
 * character pack is a snapshot of that character IN ITS OLD WORLD.
 */
function hasCharacter(pack: Pack): boolean {
  if (pack.type === 'character') return true
  return pack.type === 'collection'
    && (pack.contents || []).some((c) => c.type === 'character')
}

function formatBytes(n?: number): string {
  if (!n) return ''
  if (n < 1024) return `${n} B`
  if (n < 1024 * 1024) return `${(n / 1024).toFixed(1)} KB`
  if (n < 1024 * 1024 * 1024) return `${(n / 1024 / 1024).toFixed(1)} MB`
  return `${(n / 1024 / 1024 / 1024).toFixed(2)} GB`
}

export function MarketplaceTab() {
  const { t } = useI18n()
  const { toast } = useToast()
  const [catalogs, setCatalogs] = useState<CatalogRef[]>([])
  const [activeId, setActiveId] = useState<string>('')
  const [catalog, setCatalog] = useState<Catalog | null>(null)
  const [loading, setLoading] = useState(false)
  const [installing, setInstalling] = useState<string | null>(null)
  // Skill-package (code) install awaiting the in-app trust confirmation.
  const [pendingTrust, setPendingTrust] = useState<string | null>(null)
  const [selected, setSelected] = useState<Pack | null>(null)
  const [filterType, setFilterType] = useState<string>('')
  const [filterTag, setFilterTag] = useState<string>('')
  const [search, setSearch] = useState<string>('')
  const [building, setBuilding] = useState(false)
  // Character packs: the same two import modes the local ZIP import offers.
  // A marketplace character pack IS a character export ZIP and carries the
  // character's history in ITS world, so "re-initialize" has to be offered
  // here too — otherwise the old world's relationships, knowledge and
  // Retrospect soul files ride along into this one.
  const [mode, setMode] = useState<'full' | 'fresh'>('full')
  const [intro, setIntro] = useState('')
  const [overwrite, setOverwrite] = useState(false)

  const load = useCallback(
    async (force: boolean, id?: string) => {
      const targetId = id ?? activeId
      setLoading(true)
      try {
        const qs = new URLSearchParams()
        if (targetId) qs.set('catalog_id', targetId)
        if (force) qs.set('force', 'true')
        const data = await apiGet<Catalog>(
          `/api/content/catalog${qs.toString() ? '?' + qs : ''}`,
        )
        setCatalog(data)
        setSelected(null)
        if (data.stale) {
          // Stale is NOT a failure for the user: the cached catalog is on
          // screen and everything in it installs. Only a total fetch failure
          // (the catch below) leaves the tab without data and earns 'error'.
          toast(
            t('Showing the cached catalog — the refresh could not reach the source'),
            'info',
          )
        }
      } catch (e) {
        toast(t('Failed to load catalog') + ': ' + (e as Error).message, 'error')
        setCatalog(null)
      } finally {
        setLoading(false)
      }
    },
    [activeId, t, toast],
  )

  // Load the catalog list once. Pick the first one by default; the
  // /catalog endpoint also defaults to it when catalog_id is empty.
  useEffect(() => {
    apiGet<{ catalogs: CatalogRef[] }>('/api/content/catalogs')
      .then((d) => {
        setCatalogs(d.catalogs || [])
        if (d.catalogs && d.catalogs.length > 0 && !activeId) {
          setActiveId(d.catalogs[0].id)
        }
      })
      .catch(() => {})
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  useEffect(() => {
    if (activeId) load(false, activeId)
  }, [activeId, load])

  const allTags = useMemo(() => {
    const set = new Set<string>()
    for (const p of catalog?.packs || []) for (const tg of p.tags || []) set.add(tg)
    return Array.from(set).sort()
  }, [catalog])

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase()
    return (catalog?.packs || []).filter((p) => {
      if (filterType && p.type !== filterType) return false
      if (filterTag && !(p.tags || []).includes(filterTag)) return false
      if (q) {
        const hay = `${p.name || ''} ${p.slug || ''} ${p.description || ''}`.toLowerCase()
        if (!hay.includes(q)) return false
      }
      return true
    })
  }, [catalog, filterType, filterTag, search])

  const install = useCallback(
    async (pack: Pack, trusted = false) => {
      // Executable packages need an explicit in-app trust confirmation
      // (no JS dialogs — a warning banner replaces the button).
      if (CODE_PACK_TYPES.has(pack.type) && !trusted) {
        setPendingTrust(pack.id)
        return
      }
      const body: Record<string, unknown> = { pack_id: pack.id, catalog_id: activeId }
      if (CODE_PACK_TYPES.has(pack.type)) body.confirm_code = true
      if (hasCharacter(pack)) {
        body.overwrite = overwrite
        body.mode = mode
        if (mode === 'fresh') body.intro = intro.trim()
      }
      setPendingTrust(null)
      setInstalling(pack.id)
      try {
        const result = await apiPost<{ result?: { status?: string } }>(
          '/api/content/install',
          body,
        )
        toast(t('Installed: {name}').replace('{name}', pack.name || pack.id))
        // Soft hint: tell the user which local tab to check.
        const where = PRETTY_TYPE[pack.type] || pack.type
        toast(t('Visit the {tab} tab to use it').replace('{tab}', where))
        return result
      } catch (e) {
        toast(t('Install failed') + ': ' + (e as Error).message, 'error')
      } finally {
        setInstalling(null)
      }
    },
    [activeId, mode, intro, overwrite, t, toast],
  )

  if (loading && !catalog) return <div className="ga-loading">{t('Loading…')}</div>

  // Building a collection is a purely local export — it must stay reachable
  // even when no catalog is configured, which is why the button is repeated
  // in this placeholder.
  if (catalogs.length === 0) {
    return (
      <div className="ga-placeholder" style={{ padding: 24 }}>
        <p>
          <strong>{t('Marketplace not configured')}</strong>
        </p>
        <p>
          {t('Add at least one catalog under')}{' '}
          <code>content_marketplace.catalogs</code>{' '}
          {t('in admin settings.')}
        </p>
        <button className="ga-btn ga-btn-sm" onClick={() => setBuilding(true)}>
          {t('Build collection')}
        </button>
        {building ? <CollectionBuilder onClose={() => setBuilding(false)} /> : null}
      </div>
    )
  }

  return (
    <div className="ga-twocol">
      <aside className="ga-twocol-left">
        <div className="ga-twocol-header">
          <h3>{t('Marketplace')}</h3>
          <div className="ga-twocol-header-actions">
            <button
              className="ga-btn ga-btn-sm"
              onClick={() => setBuilding(true)}
              title={t('Pack entities of this world into one collection ZIP')}
            >
              ⧉ {t('Build collection')}
            </button>
            <button
              className="ga-btn ga-btn-sm"
              onClick={() => load(true)}
              disabled={loading}
              title={t('Re-fetch the catalog from source')}
            >
              ⟳ {t('Refresh')}
            </button>
          </div>
        </div>
        {catalogs.length > 1 ? (
          <select
            className="ga-input"
            value={activeId}
            onChange={(e) => setActiveId(e.target.value)}
            title={t('Switch between configured catalogs')}
          >
            {catalogs.map((c) => (
              <option key={c.id} value={c.id}>
                {c.name}
              </option>
            ))}
          </select>
        ) : null}
        <input
          className="ga-input"
          type="search"
          value={search}
          onChange={(e) => setSearch(e.target.value)}
          placeholder={t('Search…')}
        />
        <div className="ga-form-row" style={{ marginTop: 4 }}>
          <select
            className="ga-input"
            style={{ flex: 1 }}
            value={filterType}
            onChange={(e) => setFilterType(e.target.value)}
          >
            <option value="">{t('All types')}</option>
            {Object.entries(PRETTY_TYPE).map(([k, label]) => (
              <option key={k} value={k}>
                {label}
              </option>
            ))}
          </select>
          <select
            className="ga-input"
            style={{ flex: 1 }}
            value={filterTag}
            onChange={(e) => setFilterTag(e.target.value)}
          >
            <option value="">{t('All tags')}</option>
            {allTags.map((tg) => (
              <option key={tg} value={tg}>
                {tg}
              </option>
            ))}
          </select>
        </div>
        {filterType === 'collection' ? (
          <div style={{ marginTop: 6, fontSize: 11, opacity: 0.75 }}>
            {t(
              'Collections are built in the builder and shared as ZIP — publish applies to single packs.',
            )}
          </div>
        ) : null}
        {catalog?.stale ? (
          <div
            style={{
              marginTop: 6,
              padding: '4px 8px',
              background: '#d2992222',
              border: '1px solid #d2992255',
              borderRadius: 4,
              fontSize: 11,
              color: '#d29922',
            }}
          >
            {t('Showing cached catalog — last fetch failed.')}
          </div>
        ) : null}
        <ul className="ga-list" style={{ marginTop: 6 }}>
          {filtered.length === 0 ? (
            <li className="ga-list-empty">{t('No packs')}</li>
          ) : (
            filtered.map((p) => {
              const isActive = selected?.id === p.id
              return (
                <li key={p.id}>
                  <button
                    type="button"
                    className={`ga-list-row${isActive ? ' is-active' : ''}`}
                    onClick={() => {
                      setSelected(p)
                      // The mode choice belongs to the pack being looked at —
                      // never carry a "fresh" pick over to the next pack.
                      setMode('full'); setIntro(''); setOverwrite(false)
                    }}
                  >
                    <span className="ga-list-row-main">
                      <strong>{p.name || p.id}</strong>
                      <span className="ga-list-row-sub">
                        — {PRETTY_TYPE[p.type] || p.type}
                        {p.size_bytes ? ` · ${formatBytes(p.size_bytes)}` : ''}
                      </span>
                    </span>
                  </button>
                </li>
              )
            })
          )}
        </ul>
      </aside>
      <section className="ga-twocol-right">
        {!selected ? (
          <div className="ga-placeholder">{t('Pick a pack to see its details.')}</div>
        ) : (
          <div className="ga-form" style={{ padding: 16 }}>
            {selected.preview_image ? (
              <img
                src={selected.preview_image}
                alt=""
                style={{
                  maxWidth: '100%',
                  maxHeight: 240,
                  objectFit: 'contain',
                  borderRadius: 6,
                  marginBottom: 12,
                }}
                onError={(e) => {
                  ;(e.target as HTMLImageElement).style.display = 'none'
                }}
              />
            ) : null}
            <h2 style={{ fontSize: 18, margin: '0 0 4px' }}>
              {selected.name || selected.id}
            </h2>
            <div style={{ fontSize: 12, color: '#8b949e', marginBottom: 12 }}>
              {PRETTY_TYPE[selected.type] || selected.type}
              {selected.version ? ` · v${selected.version}` : ''}
              {selected.size_bytes ? ` · ${formatBytes(selected.size_bytes)}` : ''}
            </div>
            {selected.tags && selected.tags.length > 0 ? (
              <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap', marginBottom: 12 }}>
                {selected.tags.map((tg) => (
                  <span
                    key={tg}
                    style={{
                      fontSize: 11,
                      padding: '2px 6px',
                      borderRadius: 10,
                      background: '#21262d',
                      color: '#c9d1d9',
                    }}
                  >
                    {tg}
                  </span>
                ))}
              </div>
            ) : null}
            {selected.description ? (
              <p style={{ fontSize: 13, lineHeight: 1.5, whiteSpace: 'pre-wrap' }}>
                {selected.description}
              </p>
            ) : null}
            {selected.type === 'collection' && selected.contents && selected.contents.length > 0 ? (
              <div style={{ marginTop: 4, marginBottom: 12 }}>
                <div style={{ fontSize: 12, color: '#8b949e', marginBottom: 4 }}>
                  {t('Contents')} ({selected.contents.length}):
                </div>
                <ul
                  style={{
                    margin: 0,
                    padding: '6px 8px',
                    listStyle: 'none',
                    background: '#0d1117',
                    border: '1px solid #30363d',
                    borderRadius: 6,
                    fontSize: 12,
                    maxHeight: 220,
                    overflowY: 'auto',
                  }}
                >
                  {selected.contents.map((c, i) => (
                    <li
                      key={i}
                      style={{
                        display: 'flex',
                        justifyContent: 'space-between',
                        padding: '3px 4px',
                        borderBottom:
                          i < selected.contents!.length - 1 ? '1px solid #21262d' : 'none',
                      }}
                    >
                      <span>{c.name}</span>
                      <span style={{ color: '#8b949e' }}>
                        {PRETTY_TYPE[c.type] || c.type}
                      </span>
                    </li>
                  ))}
                </ul>
              </div>
            ) : null}
            {selected.type === 'location' && selected.room_count ? (
              <p style={{ fontSize: 12, color: '#8b949e' }}>
                {selected.room_count} {t('rooms')}
                {selected.image_count ? `, ${selected.image_count} ${t('images')}` : ''}
              </p>
            ) : null}
            {hasCharacter(selected) ? (
              <div style={{
                marginTop: 12, paddingTop: 10,
                borderTop: '1px solid var(--border, #30363d)',
              }}>
                <div style={{ fontSize: '0.82em', fontWeight: 600, marginBottom: 6 }}>
                  {t('Import mode')}
                </div>
                <label style={{ display: 'flex', alignItems: 'baseline', gap: 8,
                                padding: '3px 0', cursor: 'pointer' }}>
                  <input type="radio" name="mp-char-import-mode" checked={mode === 'full'}
                    onChange={() => setMode('full')} />
                  <span>
                    {t('Full clone')}{' '}
                    <span style={{ opacity: 0.55, fontSize: '0.82em' }}>
                      — {t('keep all history (same/compatible world)')}
                    </span>
                  </span>
                </label>
                <label style={{ display: 'flex', alignItems: 'baseline', gap: 8,
                                padding: '3px 0', cursor: 'pointer' }}>
                  <input type="radio" name="mp-char-import-mode" checked={mode === 'fresh'}
                    onChange={() => setMode('fresh')} />
                  <span>
                    {t('Fresh start (newly arrived)')}{' '}
                    <span style={{ opacity: 0.55, fontSize: '0.82em' }}>
                      — {t('keep identity, drop world-bound history')}
                    </span>
                  </span>
                </label>
                {mode === 'fresh' ? (
                  <div style={{ marginTop: 8 }}>
                    <div style={{ fontSize: '0.78em', opacity: 0.7, marginBottom: 4 }}>
                      {t('Intro memory')}
                    </div>
                    <textarea className="ga-input" rows={3} value={intro}
                      onChange={(e) => setIntro(e.target.value)}
                      placeholder={t('Short intro memory for the new arrival (editable)…')}
                      style={{ width: '100%', resize: 'vertical' }} />
                  </div>
                ) : null}
                <label style={{ display: 'flex', alignItems: 'baseline', gap: 8,
                                marginTop: 8, cursor: 'pointer' }}>
                  <input type="checkbox" checked={overwrite}
                    onChange={(e) => setOverwrite(e.target.checked)} />
                  <span>
                    {t('Replace if already present')}{' '}
                    <span style={{ opacity: 0.55, fontSize: '0.82em' }}>
                      — {t('without this, an install of a character already here fails')}
                    </span>
                  </span>
                </label>
              </div>
            ) : null}
            {CODE_PACK_TYPES.has(selected.type) && pendingTrust === selected.id ? (
              <div style={{
                marginTop: 16, padding: 12, borderRadius: 8,
                border: '1px solid #d29922', background: 'rgba(210,153,34,0.12)',
              }}>
                <p style={{ margin: '0 0 8px', fontSize: 13, color: '#e3b341' }}>
                  ⚠ {t('This skill package contains EXECUTABLE CODE. Installing runs its Python on the next skill load. Only continue if you trust the source.')}
                </p>
                <div style={{ display: 'flex', gap: 8 }}>
                  <button className="ga-btn ga-btn-primary ga-btn-sm"
                    disabled={installing === selected.id}
                    onClick={() => install(selected, true)}>
                    {installing === selected.id ? t('Installing…') : t('I trust this — install')}
                  </button>
                  <button className="ga-btn ga-btn-sm" onClick={() => setPendingTrust(null)}>
                    {t('Cancel')}
                  </button>
                </div>
              </div>
            ) : null}
            <div style={{ marginTop: 16 }}>
              <button
                className="ga-btn ga-btn-primary"
                disabled={installing === selected.id || !selected.download_url
                  || (CODE_PACK_TYPES.has(selected.type) && pendingTrust === selected.id)}
                onClick={() => install(selected)}
              >
                {installing === selected.id ? t('Installing…') : t('Install')}
              </button>
              {!selected.download_url ? (
                <span style={{ marginLeft: 8, fontSize: 12, color: '#f85149' }}>
                  {t('No download_url in pack')}
                </span>
              ) : null}
            </div>
          </div>
        )}
      </section>
      {building ? <CollectionBuilder onClose={() => setBuilding(false)} /> : null}
    </div>
  )
}
